import{_ as t,o as a,c as n,ag as i}from"./chunks/framework.CmaAMB6e.js";const g=JSON.parse('{"title":"22 · 微服务拆分","description":"","frontmatter":{"概念":"微服务拆分","技能":"system-design","阶段":"5-资深架构","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z"},"headers":[],"relativePath":"system-design/concepts/22-microservices.md","filePath":"system-design/concepts/22-microservices.md","lastUpdated":null}'),e={name:"system-design/concepts/22-microservices.md"};function r(l,s,p,d,o,h){return a(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="_22-·-微服务拆分" tabindex="-1">22 · 微服务拆分 <a class="header-anchor" href="#_22-·-微服务拆分" aria-label="Permalink to &quot;22 · 微服务拆分&quot;">​</a></h1><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>微服务不是「把单体拆小」这么简单——拆错了,你会得到<strong>分布式的单体(Distributed Monolith)</strong>:代码拆成了几十个服务,但部署、依赖、故障仍然是耦合的,比单体更痛苦。微服务拆分的本质是<strong>为「独立演进」划边界</strong>:每个服务能独立开发、独立部署、独立扩缩容、独立故障,而这些独立性的前提是<strong>数据边界清晰</strong>。</p><p>本章聚焦架构师最核心的决策:拆分的边界从哪来(业务能力/团队/数据)、服务之间怎么通信(REST/gRPC/消息)、拆完之后谁来管(注册/发现/配置/链路),以及最重要的——<strong>什么时候不该拆</strong>。微服务是手段不是目的,「一个服务维护一个领域模型」才是目的。</p><p>前端工程师对这套逻辑并不陌生:组件拆分遵循单一职责(一个组件只做一件事)、通信靠 props 与事件、组件库治理靠设计系统。微服务就是把这套思维从「函数/组件」放大到「独立部署的服务」。Monorepo 里的 package 边界、微前端的应用边界,和微服务的服务边界是同构的——只是切分的工具不同。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-拆分原则-业务能力、团队边界、数据边界" tabindex="-1">1. 拆分原则:业务能力、团队边界、数据边界 <a class="header-anchor" href="#_1-拆分原则-业务能力、团队边界、数据边界" aria-label="Permalink to &quot;1. 拆分原则:业务能力、团队边界、数据边界&quot;">​</a></h4><p>三条边界按优先级排列,<strong>数据边界是第一位的</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单体应用</span></span>
<span class="line"><span>├── 用户模块(user 表)  ──┐</span></span>
<span class="line"><span>├── 商品模块(product 表) ├─ 按业务能力拆分</span></span>
<span class="line"><span>├── 订单模块(order 表)   ─┘</span></span>
<span class="line"><span>└── 共享的 user 表被多个模块读写 ← 数据耦合是拆分的最大障碍</span></span>
<span class="line"><span></span></span>
<span class="line"><span>拆分后:</span></span>
<span class="line"><span>┌ 用户服务(独立库 user_db)  ── 数据边界:谁写这张表,谁拥有这个服务</span></span>
<span class="line"><span>├ 商品服务(独立库 product_db)</span></span>
<span class="line"><span>└ 订单服务(独立库 order_db,只读引用 user_id)</span></span></code></pre></div><ul><li><strong>业务能力边界</strong>:按 DDD 的限界上下文(Bounded Context)切——「订单」与「库存」是两个不同语言的世界,理应分开;</li><li><strong>团队边界(康威定律)</strong>:系统架构会镜像沟通结构。拆分的服务必须能由<strong>一个小团队端到端拥有</strong>(设计→开发→运维),否则边界会漂移;</li><li><strong>数据边界</strong>:一个服务独占自己的数据库。两个服务共享一张表 = 这两个服务其实还是一个服务。</li></ul><h4 id="_2-服务间通信-rest-grpc-消息" tabindex="-1">2. 服务间通信:REST / gRPC / 消息 <a class="header-anchor" href="#_2-服务间通信-rest-grpc-消息" aria-label="Permalink to &quot;2. 服务间通信:REST / gRPC / 消息&quot;">​</a></h4><table tabindex="0"><thead><tr><th>维度</th><th>REST/HTTP</th><th>gRPC</th><th>消息队列</th></tr></thead><tbody><tr><td>语义</td><td>请求-响应</td><td>请求-响应(强类型 IDL)</td><td>异步事件</td></tr><tr><td>性能</td><td>中等(JSON 序列化)</td><td>高(Protobuf + HTTP/2)</td><td>高(批量)</td></tr><tr><td>耦合</td><td>服务接口耦合</td><td>接口契约(proto)耦合</td><td>解耦,只依赖事件</td></tr><tr><td>失败处理</td><td>调用方感知</td><td>调用方感知</td><td>天然缓冲、可重试</td></tr><tr><td>适用</td><td>对外 API、低频查询</td><td>服务间高频 RPC</td><td>解耦、削峰、异步链路</td></tr></tbody></table><p>经验法则:<strong>读操作用同步(REST/gRPC),写操作倾向异步(消息)</strong>。同步调用链会放大故障(一个服务慢,整条链路跟着慢),所以深度超过 3 层的同步链是坏味道。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># gRPC 契约示例:proto 文件是服务间的&quot;接口文档&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># order.proto</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">service OrderService {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    rpc CreateOrder(CreateOrderRequest) returns (OrderReply);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">message CreateOrderRequest {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    string user_id = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    string sku_id = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    int32 qty = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    string idempotency_key = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 幂等键,防重复下单</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h4 id="_3-服务治理-注册、发现、配置" tabindex="-1">3. 服务治理:注册、发现、配置 <a class="header-anchor" href="#_3-服务治理-注册、发现、配置" aria-label="Permalink to &quot;3. 服务治理:注册、发现、配置&quot;">​</a></h4><p>服务实例的地址是动态的(扩缩容、宕机),需要一套「电话簿」:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[服务实例 A&lt;br/&gt;启动时注册] --&gt; R[注册中心&lt;br/&gt;Nacos/Consul/etcd]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B[服务实例 B] --&gt; R</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C[服务实例 C] --&gt; R</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G[网关] -- 发现服务地址 --&gt; R</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G -- 负载均衡转发 --&gt; A</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G -- 负载均衡转发 --&gt; B</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G -- 负载均衡转发 --&gt; C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R -- 健康检查:剔除不健康实例 --&gt; A</span></span></code></pre></div><ul><li><strong>注册中心</strong>:服务启动注册、心跳续约、故障剔除——注意注册中心本身就是一致性系统(21 篇),选 CP 还是 AP 是另一道权衡;</li><li><strong>配置中心</strong>:配置(限流阈值、开关)动态下发,避免改配置就重启;</li><li><strong>网关</strong>:统一入口,负责路由、鉴权、限流,业务服务彼此不直接暴露。</li></ul><p>治理的成熟度决定微服务的成败:没有健康检查与熔断的微服务,故障会像多米诺骨牌一样传播(13 篇的熔断/限流/舱壁是治理的组成部分)。</p><h4 id="_4-分布式链路-黑盒里装探头" tabindex="-1">4. 分布式链路:黑盒里装探头 <a class="header-anchor" href="#_4-分布式链路-黑盒里装探头" aria-label="Permalink to &quot;4. 分布式链路:黑盒里装探头&quot;">​</a></h4><p>一个请求跨 5 个服务,定位慢在哪必须靠<strong>链路追踪</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 → 网关(trace_id: a1b2...) → 订单服务(span 1: 10ms)</span></span>
<span class="line"><span>                                 → 库存服务(span 2: 45ms) ← 最慢</span></span>
<span class="line"><span>                                 → 支付服务(span 3: 5ms)</span></span></code></pre></div><p>Trace ID 贯穿所有调用,每个服务上报 span(起止时间、标签),聚合后还原整条调用链(OpenTelemetry + Jaeger/Zipkin)。线上排查顺序永远是:看链路 → 定位最慢 span → 看该服务日志/指标。</p><h4 id="_5-什么时候不该拆-反面清单" tabindex="-1">5. 什么时候不该拆(反面清单) <a class="header-anchor" href="#_5-什么时候不该拆-反面清单" aria-label="Permalink to &quot;5. 什么时候不该拆(反面清单)&quot;">​</a></h4><ul><li><strong>团队 &lt; 2 个</strong>:拆分后没人维护,先合;</li><li><strong>业务域还在探索</strong>:领域模型天天变,拆分会放大每次改动的成本;</li><li><strong>调用链深度 &gt; 5 且无法解耦</strong>:拆了等于没拆(分布式单体);</li><li><strong>数据边界切不干净</strong>:多个服务共享同一张表,拆了必乱。</li></ul><p>业界共识:** 先模块化单体(Modular Monolith)**,包内划清边界、禁止跨模块直接访问数据库,等规模与团队到位再逐步拆——拆分是演进的结果,不是起点的姿态。</p><h4 id="_6-与前端组件拆分-monorepo-对照" tabindex="-1">6. 与前端组件拆分 / Monorepo 对照 <a class="header-anchor" href="#_6-与前端组件拆分-monorepo-对照" aria-label="Permalink to &quot;6. 与前端组件拆分 / Monorepo 对照&quot;">​</a></h4><table tabindex="0"><thead><tr><th>前端概念</th><th>微服务对应物</th><th>共同本质</th></tr></thead><tbody><tr><td>组件单一职责</td><td>服务业务能力边界</td><td>高内聚</td></tr><tr><td>props 契约 / TS interface</td><td>API 契约 / proto IDL</td><td>边界即契约</td></tr><tr><td>组件树 props 钻透</td><td>深同步调用链</td><td>都应避免</td></tr><tr><td>Monorepo 多 package</td><td>多服务仓库</td><td>独立演进</td></tr><tr><td>微前端应用边界</td><td>微服务边界</td><td>运行时隔离</td></tr><tr><td>设计系统/组件库</td><td>服务网格/网关</td><td>公共治理层</td></tr></tbody></table><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>按技术分层拆</strong>:把 controller/service/dao 拆成三个服务——这是职责拆分,不是领域拆分,只会增加无意义的网络开销。</li><li><strong>共享数据库表</strong>:两个服务写同一张表,数据边界失效,升级/迁移必须一起发版。</li><li><strong>同步调用链越拉越长</strong>:下单同步调库存、支付、优惠券、物流……任何一个慢全链路慢,且没有缓冲,雪崩风险极高。</li><li><strong>没有契约管理就拆</strong>:API 变更不兼容、无版本控制,消费者各自为战,「每个服务独立演进」沦为口号。</li><li><strong>忽略分布式事务成本</strong>:拆完才发现跨服务写操作(20 篇)比拆之前复杂一个量级。</li><li><strong>为「微服务」而微服务</strong>:两三个人的团队拆出十个服务,运维负担远超收益。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>:把「博客系统」(用户/文章/评论/通知)画出微服务拆分图:标注每个服务的数据表边界、服务间调用方向,并指出其中哪个调用应该改造成异步。</li><li><strong>进阶</strong>:为订单服务设计一份 REST vs gRPC vs 消息的通信矩阵(与库存、支付、物流、用户各用什么、为什么),并画注册中心 + 网关的治理架构图。</li><li><strong>综合</strong>:对一个现有单体做「拆 or 不拆」的完整评估:列出候选服务、数据边界、团队人数、拆分顺序(哪两个服务先拆),以及拆分后引入的分布式事务/链路/治理成本清单。</li></ol><blockquote><p>用 <code>/practice system-design 微服务拆分</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端</th><th>微服务</th></tr></thead><tbody><tr><td>组件拆分(SRP、单一职责)</td><td>按业务能力拆服务</td></tr><tr><td>props / 事件通信</td><td>REST / gRPC / 消息</td></tr><tr><td>React Context / 全局 store</td><td>注册中心 / 配置中心</td></tr><tr><td>组件树 props 钻透(坏味道)</td><td>深同步调用链(坏味道)</td></tr><tr><td>Monorepo 多 package 独立发布</td><td>多服务独立部署</td></tr><tr><td>微前端(应用间隔离)</td><td>微服务(进程级隔离)</td></tr><tr><td>设计系统统一 UI 治理</td><td>API 网关统一治理</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://microservices.io/" target="_blank" rel="noreferrer">Microservices.io(Chris Richardson 模式目录)</a></li><li><a href="https://www.oreilly.com/library/view/microservices-patterns/9781617294549/" target="_blank" rel="noreferrer">《微服务架构设计模式》(同作者)</a></li><li><a href="https://grpc.io/docs/" target="_blank" rel="noreferrer">gRPC 官方文档</a></li><li><a href="https://opentelemetry.io/docs/" target="_blank" rel="noreferrer">OpenTelemetry 规范</a></li><li><a href="https://martinfowler.com/bliki/MonolithFirst.html" target="_blank" rel="noreferrer">Martin Fowler:MonolithFirst</a></li></ul>`,37)])])}const k=t(e,[["render",r]]);export{g as __pageData,k as default};
